// === Tab: mySketch ===
// let Risou
// https://risoume.github.io

let s, c;
let scale = 0.9;
let m = 80;

function setup() {
  createCanvas(600, 600);
  noStroke();
  noLoop();
}

function draw() {
  background("#313131");
  s = width-2*m;
  translate(m, m);

  while (s > 10) {
		c = map(s, 10, width-2*m, 0, 1000);
		if (c > 255) c = 255;
    fill(c);
    rect(0, 0, s, s);
    float[][] coor = {{0, 0}, {s-s*scale, 0}, {0, s-s*scale}, {s-s*scale, s-s*scale}};
    let q = int(random(coor.length));
    translate(coor[q][0], coor[q][1]);
    s *= scale;
  }
}

function mouseReleased() {
  redraw();
}

